'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),vm=require('node:vm');
const {inspectPortalPage}=require('./portal-inspection');
const OFFICIAL='https://visa.mofa.gov.sa';
class Element{
 constructor(tag,attrs={},text='',children=[]){this.tagName=tag.toUpperCase();this.nodeType=1;this.attrs={...attrs};this.ownText=text;this.children=children;for(const child of children)child.parent=this;this.hidden=false;this.disabled=false;this.multiple=false;this.style={display:'block',visibility:'visible'};this.labels=[];this.options=[];Object.defineProperty(this,'value',{get(){throw Error('INPUT_VALUE_WAS_READ');}});}
 getAttribute(name){if(name==='value'&&this.tagName!=='OPTION'&&!(this.tagName==='INPUT'&&['submit','button','reset','radio'].includes(this.attrs.type)))throw Error('INPUT_VALUE_ATTRIBUTE_WAS_READ');return Object.hasOwn(this.attrs,name)?this.attrs[name]:null;}
 hasAttribute(name){return Object.hasOwn(this.attrs,name);}
 get parentElement(){return this.parent||null;}
 get childNodes(){return [...(this.ownText?[{nodeType:3,textContent:this.ownText}]:[]),...this.children];}
 get textContent(){return this.ownText+this.children.map(c=>c.textContent).join('');}
 getClientRects(){return this.noRect?[]:[{}];}
 closest(selector){let node=this;while(node){if(selector==='.form-group'){if((node.attrs?.class||'').split(/\s+/).includes('form-group'))return node;}else if(node.hidden||node.attrs?.['aria-hidden']==='true')return node;node=node.parent;}return null;}
 cloneNode(){const c=new Element(this.tagName,this.attrs,this.ownText,this.children.map(n=>n.cloneNode(true)));return c;}
 querySelectorAll(selector){const tags=selector.split(',');const all=[];function walk(n){for(const child of n.children){if(tags.some(tag=>tag===child.tagName.toLowerCase()||tag.startsWith('.')&&(child.attrs.class||'').split(/\s+/).includes(tag.slice(1))))all.push(child);walk(child);}}walk(this);return all;}
 contains(other){return this===other||this.children.some(child=>child.contains(other));}
 remove(){if(this.parent)this.parent.children=this.parent.children.filter(c=>c!==this);}
}
function mockPage(elements=[],{url=OFFICIAL+'/SmartForm/TraditionalApp?token=PRIVATE#secret',frameUrl=url,afterUrl,locationHref=url,jQuery}={}){
 const pool=[];const add=el=>{pool.push(el);el.children.forEach(add);};elements.forEach(add);let reads=0;
 const document={body:pool.find(e=>e.tagName==='BODY')||new Element('body',{},'',elements),querySelector:selector=>pool.find(e=>e.tagName.toLowerCase()===selector)||null,getElementById:id=>pool.find(e=>e.attrs.id===id)||null,querySelectorAll(selector){if(selector.startsWith('#')){const id=selector.slice(1).replace(/\\(.)/g,'$1');return pool.filter(e=>e.attrs.id===id);}if(selector==='[data-valmsg-for]')return pool.filter(e=>e.attrs['data-valmsg-for']!==undefined);if(selector==='script[src]')return pool.filter(e=>e.tagName==='SCRIPT'&&e.attrs.src!==undefined);if(selector==='script:not([src])')return pool.filter(e=>e.tagName==='SCRIPT'&&e.attrs.src===undefined);if(selector==='a[href]')return pool.filter(e=>e.tagName==='A'&&e.attrs.href!==undefined);if(selector.startsWith('.modal.in'))return pool.filter(e=>{const classes=(e.attrs.class||'').split(/\s+/);return classes.includes('modal')&&(classes.includes('in')||classes.includes('show'))||e.attrs.role==='dialog'||e.tagName==='DIALOG'&&Object.hasOwn(e.attrs,'open')||classes.some(c=>['swal-modal','sweet-alert','swal2-popup'].includes(c));});if(selector.startsWith('.validation-summary-errors'))return pool.filter(e=>(e.attrs.class||'').split(/\s+/).some(c=>['validation-summary-errors','field-validation-error','alert-danger'].includes(c))||e.attrs.role==='alert');const tags=selector.split(',');return pool.filter(e=>tags.includes(e.tagName.toLowerCase()));}};
 const location=new URL(locationHref);const context=vm.createContext({document,jQuery,location:{origin:location.origin,href:location.href,pathname:location.pathname},URL,CSS:{escape:id=>id.replace(/([.:])/g,'\\$1')},getComputedStyle:el=>el.style});
 return {url:()=>{reads++;return reads>1&&afterUrl?afterUrl:url;},mainFrame:()=>({url:()=>frameUrl}),evaluate:async fn=>vm.runInContext('('+fn.toString()+')()',context),frames(){throw Error('CHILD_FRAMES_MUST_NOT_BE_READ');}};
}
const label=text=>new Element('label',{},text);
test('requires official top-level URL and main frame before evaluating',async()=>{for(const config of [{url:'https://evil.test/'},{frameUrl:'https://evil.test/'},{url:'http://visa.mofa.gov.sa/'},{url:'https://user:pass@visa.mofa.gov.sa/'}])await assert.rejects(inspectPortalPage(mockPage([] ,config)),/PORTAL_ORIGIN_INVALID/);});
test('rejects navigation away while inspection is in flight',async()=>{await assert.rejects(inspectPortalPage(mockPage([],{afterUrl:'https://evil.test/'})),/PORTAL_ORIGIN_INVALID/);await assert.rejects(inspectPortalPage(mockPage([],{locationHref:'https://evil.test/'})),/PORTAL_ORIGIN_INVALID/);});
test('returns original top-document path without query hash or title',async()=>{const result=await inspectPortalPage(mockPage([new Element('h1',{},'New visa application')]));assert.equal(result.path,'/SmartForm/TraditionalApp');assert.equal(result.headings[0],'New visa application');assert.equal(Object.hasOwn(result,'title'),false);assert.equal(JSON.stringify(result).includes('PRIVATE'),false);});
test('never reads input values, textarea content, passwords or hidden/token/challenge fields',async()=>{const normal=new Element('input',{id:'PASSPORTnumber',name:'PASSPORTnumber',type:'text',maxlength:'20',required:''});normal.labels=[label('Passport number')];const privateArea=new Element('textarea',{id:'address',name:'address'},'PRIVATE_TEXTAREA_CONTENT');const wrapped=new Element('label',{},'Saudi address ',[privateArea]);privateArea.labels=[wrapped];const result=await inspectPortalPage(mockPage([normal,wrapped,new Element('input',{id:'Password',type:'password'}),new Element('input',{id:'nonce',type:'hidden'}),new Element('input',{id:'Captcha',type:'text'}),new Element('input',{id:'OTPCode',type:'text'}),new Element('input',{id:'txtCode',type:'text'}),new Element('input',{id:'token',type:'text'})]));assert.equal(result.controls.length,2);assert.equal(result.controls[0].id,'PASSPORTnumber');assert.equal(result.controls[0].required,true);assert.equal(result.controls[0].maxLength,20);assert.equal(result.controls[1].label,'Saudi address');const serialized=JSON.stringify(result);for(const secret of ['PRIVATE_TEXTAREA_CONTENT','Password','Captcha','nonce','token'])assert.equal(serialized.includes(secret),false);});
test('filters hidden CSS controls and ignores child frame documents',async()=>{const visible=new Element('input',{id:'visible'}),hidden=new Element('input',{id:'hiddenCss'}),other=new Element('input',{id:'ariaHidden','aria-hidden':'true'});hidden.style.display='none';const frame=new Element('iframe',{src:'https://evil.test'});const result=await inspectPortalPage(mockPage([visible,hidden,other,frame]));assert.deepEqual(Array.from(result.controls,c=>c.id),['visible']);});
test('redacts emails, long digit runs, GUIDs, opaque strings and bidi characters in captions',async()=>{const heading=new Element('h2',{},'مرحبا owner@example.com 784123456789012 12345678-1234-1234-1234-123456789abc \u202e'+ 'X'.repeat(45));const result=await inspectPortalPage(mockPage([heading]));const text=result.headings[0];assert.equal(text.includes('owner@'),false);assert.equal(text.includes('784123'),false);assert.equal(text.includes('\u202e'),false);assert.equal(text.includes('X'.repeat(45)),false);assert.ok(text.length<=120);});
test('same-origin links only, with unique safe ID selector and path without secrets',async()=>{const a=new Element('a',{id:'new:visa',href:'/SmartForm/Agreement?token=PRIVATE#private'},'Add a new application');const duplicate1=new Element('a',{id:'dup',href:OFFICIAL+'/MyApplications?secret=x'},'My applications'),duplicate2=new Element('a',{id:'dup',href:'/Home'},'Home');const result=await inspectPortalPage(mockPage([a,duplicate1,duplicate2,new Element('a',{href:'https://evil.test/'},'External'),new Element('a',{href:'javascript:alert(1)'},'JS'),new Element('a',{href:'https://visa.mofa.gov.sa.evil.test/'},'Spoof')]));assert.equal(result.links.length,3);assert.equal(result.links[0].path,'/SmartForm/Agreement');assert.equal(result.links[0].selector,'#new\\:visa');assert.equal(result.links[1].selector,null);assert.equal(JSON.stringify(result).includes('PRIVATE'),false);});
test('public country and visa option labels/short codes only, never selected values',async()=>{const visa=new Element('select',{id:'VisaKind',name:'VisaKind'});visa.options=[new Element('option',{value:'19'},'Tourism'),new Element('option',{value:'SECRET_LONG_TOKEN_123456'},'Secret')];const residence=new Element('select',{id:'ddlResidenceCountry'});residence.options=[new Element('option',{value:'ARE'},'United Arab Emirates')];const privateSelect=new Element('select',{id:'SavedApplicant'});privateSelect.options=[new Element('option',{value:'123'},'PRIVATE_APPLICANT')];const result=await inspectPortalPage(mockPage([visa,residence,privateSelect]));assert.equal(result.controls[0].options[0].value,'19');assert.equal(result.controls[0].options.length,1);assert.equal(result.controls[1].options[0].value,'ARE');assert.equal(result.controls[2].options,undefined);assert.equal(JSON.stringify(result).includes('PRIVATE_APPLICANT'),false);});
test('file metadata and original safe button types returned without field values',async()=>{const upload=new Element('input',{id:'passportUpload',type:'file',accept:'.jpg,.png'});upload.multiple=true;const submit=new Element('button',{id:'save',type:'submit'},'Save');const plain=new Element('button',{id:'back',type:'button'},'Back');const result=await inspectPortalPage(mockPage([upload,submit,plain]));assert.equal(result.controls[0].accept,'.jpg,.png');assert.equal(result.controls[0].multiple,true);assert.equal(result.buttons[0].type,'submit');assert.equal(result.buttons[1].type,'button');assert.equal(result.buttons[0].selector,'#save');});
test('caps returned controls links headings and label lengths',async()=>{const controls=Array.from({length:130},(_,i)=>new Element('input',{id:'field'+i,'aria-label':'a'.repeat(300)}));const links=Array.from({length:100},(_,i)=>new Element('a',{id:'link'+i,href:'/Home'},'b'.repeat(300)));const headings=Array.from({length:30},()=>new Element('h1',{},'c'.repeat(300)));const result=await inspectPortalPage(mockPage([...controls,...links,...headings]));assert.equal(result.controls.length,100);assert.equal(result.links.length,80);assert.equal(result.headings.length,16);assert.ok(result.controls.every(x=>x.label.length<=120));assert.ok(result.links.every(x=>x.label.length<=120));assert.ok(result.headings.every(x=>x.length<=120));});

test('retains public Select2 underlying select metadata only with a visible associated container',async()=>{const select=new Element('select',{id:'ddlResidenceCountry',class:'select2-hidden-accessible','aria-hidden':'true'});select.noRect=true;select.options=[new Element('option',{value:'ARE'},'United Arab Emirates')];const container=new Element('span',{id:'select2-ddlResidenceCountry-container'},'PRIVATE_SELECTED_TEXT');const hidden=new Element('select',{id:'Nationality',class:'select2-hidden-accessible','aria-hidden':'true'});const hiddenContainer=new Element('span',{id:'select2-Nationality-container'},'PRIVATE_SELECTED_OTHER');hiddenContainer.style.display='none';const result=await inspectPortalPage(mockPage([select,container,hidden,hiddenContainer]));assert.equal(result.controls.length,1);assert.equal(result.controls[0].id,'ddlResidenceCountry');assert.equal(result.controls[0].options[0].value,'ARE');assert.equal(JSON.stringify(result).includes('PRIVATE_SELECTED'),false);});

test('form ownership metadata includes only method and same-origin sanitized action path',async()=>{const form=new Element('form',{method:'POST',action:'/SmartForm/Save?token=PRIVATE#secret'});form.method='post';form.action=OFFICIAL+'/SmartForm/Save?token=PRIVATE#secret';const input=new Element('input',{id:'EFIRSTNAME'});input.form=form;const button=new Element('button',{id:'saveForm',type:'submit'},'Save');button.form=form;const foreignForm=new Element('form',{method:'post',action:'https://foreign.test/upload?secret=PRIVATE'});foreignForm.method='post';foreignForm.action='https://foreign.test/upload?secret=PRIVATE';const foreign=new Element('input',{id:'fileUpload',type:'file'});foreign.form=foreignForm;const noForm=new Element('input',{id:'ajaxField'});const result=await inspectPortalPage(mockPage([input,button,foreign,noForm]));assert.equal(result.controls[0].hasForm,true);assert.equal(result.controls[0].formMethod,'post');assert.equal(result.controls[0].formActionPath,'/SmartForm/Save');assert.equal(result.buttons[0].hasForm,true);assert.equal(result.buttons[0].formMethod,'post');assert.equal(result.buttons[0].formActionPath,'/SmartForm/Save');assert.equal(result.controls[2].hasForm,true);assert.equal(result.controls[2].formActionPath,null);assert.equal(result.controls[3].hasForm,false);assert.equal(result.controls[3].formMethod,null);assert.equal(result.controls[3].formActionPath,null);assert.equal(JSON.stringify(result).includes('PRIVATE'),false);assert.equal(JSON.stringify(result).includes('foreign.test'),false);});

test('static input action captions returned without reading editable value properties',async()=>{const save=new Element('input',{id:'Save',type:'submit',value:'Save application'});const back=new Element('input',{id:'Back',type:'button',value:'Back'});const reset=new Element('input',{id:'Reset',type:'reset',value:'Reset'});const sensitive=new Element('input',{id:'Captcha',type:'button',value:'PRIVATE_CHALLENGE'});const result=await inspectPortalPage(mockPage([save,back,reset,sensitive]));assert.deepEqual(Array.from(result.buttons,b=>[b.tag,b.type,b.label]),[['input','submit','Save application'],['input','button','Back'],['input','reset','Reset']]);assert.equal(JSON.stringify(result).includes('PRIVATE_CHALLENGE'),false);});
test('ASP.NET and aria required metadata included without returning validation attribute contents',async()=>{const a=new Element('input',{id:'FirstName','data-val-required':'PRIVATE_REQUIRED_TEXT'}),b=new Element('input',{id:'FamilyName','aria-required':'true'}),c=new Element('input',{id:'MiddleName','aria-required':'false'});const result=await inspectPortalPage(mockPage([a,b,c]));assert.deepEqual(Array.from(result.controls,c=>c.required),[true,true,false]);assert.equal(JSON.stringify(result).includes('PRIVATE_REQUIRED_TEXT'),false);});
test('h4 to h6 and bounded visible validation alerts use same value-free redaction',async()=>{const field=new Element('textarea',{id:'explanation'},'PRIVATE_FIELD_CONTENT');const nested=new Element('div',{class:'validation-summary-errors'},'Error owner@example.test 784123456789012 ',[field]);const hidden=new Element('div',{class:'alert-danger'},'PRIVATE_HIDDEN_ALERT');hidden.hidden=true;const extra=Array.from({length:20},()=>new Element('div',{role:'alert'},'a'.repeat(300)));const result=await inspectPortalPage(mockPage([new Element('h4',{},'Details'),new Element('h5',{},'Upload'),new Element('h6',{},'Review'),nested,hidden,...extra]));assert.deepEqual(Array.from(result.headings),['Details','Upload','Review']);assert.equal(result.alerts.length,12);assert.ok(result.alerts.every(v=>v.length<=120));for(const secret of ['owner@','784123','PRIVATE_FIELD_CONTENT','PRIVATE_HIDDEN_ALERT'])assert.equal(JSON.stringify(result.alerts).includes(secret),false);});
test('expanded public select metadata and static radio choices never read current selection',async()=>{const names=['Sex','Gender','MaritalStatus','SocialStatus','Transport','ArrivalPort','VisitTimes','VisitDuration','VisaValid','Period','Occupation','health.hospitalizedOrEmergency','HasInsuranceYesNo'];const fields=names.map(id=>{const el=new Element('select',{id});el.options=[new Element('option',{value:'1'},'Yes'),new Element('option',{value:'false'},'No')];return el;});const radio=new Element('input',{id:'MaleChoice',type:'radio',value:'M'});Object.defineProperty(radio,'checked',{get(){throw Error('CHECKED_STATE_WAS_READ');}});const privateRadio=new Element('input',{id:'savedApplicant',type:'radio',value:'PRIVATE_APPLICANT_ID'});const result=await inspectPortalPage(mockPage([...fields,radio,privateRadio]));assert.ok(result.controls.slice(0,names.length).every(c=>c.options.length===2));assert.equal(result.controls[names.length].publicChoice,'M');assert.equal(result.controls[names.length+1].publicChoice,undefined);assert.equal(JSON.stringify(result).includes('PRIVATE_APPLICANT_ID'),false);});

test('agreement text appears only on exact agreement path and omits editable hidden script and navigation text',async()=>{const hidden=new Element('p',{},'PRIVATE_HIDDEN_LEGAL');hidden.hidden=true;const hiddenCss=new Element('p',{},'PRIVATE_HIDDEN_CSS');hiddenCss.style.display='none';const article=new Element('main',{},'',[new Element('header',{},'PRIVATE_HEADER'),new Element('nav',{},'PRIVATE_NAV'),new Element('p',{},'Service agreement owner@example.test 784123456789012'),new Element('p',{},'Visible clause ',[new Element('textarea',{id:'privateEntry'},'PRIVATE_TYPED_TEXT'),new Element('input',{id:'privateInput',value:'PRIVATE_VALUE'}),new Element('button',{},'PRIVATE_BUTTON')]),new Element('script',{},'PRIVATE_SCRIPT'),new Element('style',{},'PRIVATE_STYLE'),new Element('noscript',{},'PRIVATE_NOSCRIPT'),hidden,hiddenCss,new Element('footer',{},'PRIVATE_FOOTER')]);const agreed=await inspectPortalPage(mockPage([article],{url:OFFICIAL+'/SmartForm/Agreement?private=SECRET#secret'}));assert.match(agreed.agreementText,/Service agreement/);assert.match(agreed.agreementText,/Visible clause/);for(const value of ['PRIVATE_','owner@','784123','SECRET'])assert.equal(agreed.agreementText.includes(value),false);const other=await inspectPortalPage(mockPage([article],{url:OFFICIAL+'/SmartForm/TraditionalApp'}));assert.equal(Object.hasOwn(other,'agreementText'),false);const similar=await inspectPortalPage(mockPage([article],{url:OFFICIAL+'/SmartForm/Agreement/other'}));assert.equal(Object.hasOwn(similar,'agreementText'),false);});
test('agreement body fallback captures visible legal paragraphs and caps text at eight thousand characters',async()=>{const body=new Element('body',{},'',[new Element('nav',{},'PRIVATE_NAV'),new Element('article',{},'',[new Element('p',{},'Legal clause '.repeat(1000))])]);const result=await inspectPortalPage(mockPage([body],{url:OFFICIAL+'/SmartForm/Agreement'}));assert.equal(result.agreementText.length,8000);assert.equal(result.agreementText.includes('PRIVATE_NAV'),false);assert.match(result.agreementText,/Legal clause/);});

test('select options capped at sixty with full-list relevant option priority and total five hundred budget',async()=>{const make=(id,last)=>{const el=new Element('select',{id});el.options=Array.from({length:250},(_,i)=>new Element('option',{value:String(i+1)},'Public option '+i));el.options.push(new Element('option',{value:'999'},last));return el;};const fields=[make('VisaKind','Tourism'),make('Nationality','Syria'),make('ddlResidenceCountry','United Arab Emirates'),make('EmbassyCode','Abu Dhabi'),make('PASSPORType','عادي'),make('NUMBER_OF_ENTRIES','Multiple'),make('Number_Entry_Day','365'),make('RELIGION','Islam'),make('SOCIAL_STATUS','Single')];const result=await inspectPortalPage(mockPage(fields));assert.ok(result.controls.every(c=>c.options.length<=60));assert.ok(result.controls.reduce((n,c)=>n+c.options.length,0)<=500);for(let i=0;i<8;i++){assert.equal(result.controls[i].optionCount,251);if(i>0)assert.ok(result.controls[i].options.some(o=>o.value==='999'));}assert.ok(result.controls[3].options.some(o=>o.label==='Abu Dhabi'));});
