test('unique form-group static label fallback excludes rendered Select2 text and ambiguous groups',async()=>{const el=new Element('select',{id:'EmbassyCode'});el.options=[new Element('option',{value:'214'},'Abu Dhabi')];const labelNoFor=new Element('label',{class:'control-label'},'Mission ',[new Element('span',{class:'select2-selection__rendered'},'PRIVATE_SELECTED_VALUE')]);const group=new Element('div',{class:'form-group'},'',[labelNoFor,el,new Element('input',{type:'hidden',id:'Bookkeeping'})]);const a=new Element('input',{id:'fieldA'}),b=new Element('input',{id:'fieldB'});const ambiguous=new Element('div',{class:'form-group'},'',[new Element('label',{},'Shared'),a,b]);const result=await inspectPortalPage(mockPage([group,ambiguous]));assert.equal(result.controls[0].label,'Mission');assert.equal(result.controls.find(c=>c.id==='fieldA').label,'');assert.equal(result.controls.find(c=>c.id==='fieldB').label,'');assert.equal(JSON.stringify(result).includes('PRIVATE_SELECTED_VALUE'),false);});
test('SmartForm CAPTCHA returns only verified same-origin source path and known IDs',async()=>{const input=new Element('input',{id:'Captcha',type:'text',value:'PRIVATE_CODE'});const image=new Element('img',{id:'imgCaptcha',src:'/Base/GetRandomCaptchaImage?token=PRIVATE_TOKEN&code=SECRET#secret'});const foreign=new Element('img',{id:'otherCaptcha',src:'https://evil.test/Base/GetRandomCaptchaImage?secret=PRIVATE'});const result=await inspectPortalPage(mockPage([input,image,foreign]));assert.deepEqual(JSON.parse(JSON.stringify(result.captcha)),{visible:true,inputId:'Captcha',imageId:'imgCaptcha',sourcePath:'/Base/GetRandomCaptchaImage',refreshControls:[]});for(const secret of ['PRIVATE_','SECRET','evil.test','?token'])assert.equal(JSON.stringify(result).includes(secret),false);assert.equal(result.controls.some(c=>c.id==='Captcha'),false);const login=await inspectPortalPage(mockPage([input,image],{url:OFFICIAL+'/Account/Loginindividuals'}));assert.equal(Object.hasOwn(login,'captcha'),false);const untrusted=await inspectPortalPage(mockPage([input,foreign]));assert.equal(untrusted.captcha.visible,false);assert.equal(untrusted.captcha.inputId,null);assert.equal(untrusted.captcha.sourcePath,null);});

