test('health insurance questions come from exact named public groups without answers or editable content',async()=>{const names=['DeclarationForms[0].Q1_IsReceivingEmergencyTreatment','DeclarationForms[0].Q2_HavePermenantInjury','DeclarationForms[0].Q3_HaveCongenitalDisorders'];const questions=['هل تتلقى حاليًا علاجًا طارئًا؟','هل لديك إصابة دائمة؟','هل لديك اضطرابات خلقية؟'];const groups=names.map((name,index)=>{const yes=new Element('input',{id:'healthYes'+index,name,type:'radio',value:'true'}),no=new Element('input',{id:'healthNo'+index,name,type:'radio',value:'false'});Object.defineProperty(yes,'checked',{get(){throw Error('HEALTH_ANSWER_STATE_READ');}});Object.defineProperty(no,'checked',{get(){throw Error('HEALTH_ANSWER_STATE_READ');}});const yesLabel=new Element('label',{},'نعم ',[yes]),noLabel=new Element('label',{},'لا ',[no]);yes.labels=[yesLabel];no.labels=[noLabel];const hidden=new Element('span',{},'PRIVATE_HIDDEN_QUESTION');hidden.hidden=true;return new Element('fieldset',{class:'form-group'},'',[new Element('legend',{},questions[index]),yesLabel,noLabel,hidden,new Element('span',{class:'select2-selection__rendered'},'PRIVATE_SELECTED_ANSWER'),new Element('script',{},'PRIVATE_SCRIPT')]);});const result=await inspectPortalPage(mockPage(groups,{url:OFFICIAL+'/SmartForm/HealthInsuranceInfo/123456789?private=SECRET'}));assert.equal(result.healthQuestions.length,3);assert.deepEqual(Array.from(result.healthQuestions,item=>item.name),names);assert.deepEqual(Array.from(result.healthQuestions,item=>item.question),questions);assert.ok(result.healthQuestions.every(item=>item.source==='legend'));for(const secret of ['PRIVATE_','true','false','نعم','لا ','SECRET'])assert.equal(JSON.stringify(result.healthQuestions).includes(secret),false);const other=await inspectPortalPage(mockPage(groups));assert.equal(Object.hasOwn(other,'healthQuestions'),false);});

test('health question association supports visible aria heading and safe group fallback but refuses mixed personal groups',async()=>{const firstName='DeclarationForms[0].Q1_IsReceivingEmergencyTreatment',secondName='DeclarationForms[0].Q2_HavePermenantInjury',thirdName='DeclarationForms[0].Q3_HaveCongenitalDisorders';const heading=new Element('h4',{id:'healthEmergencyQuestion'},'Are you receiving emergency treatment? owner@example.test 123456789');const first=new Element('select',{name:firstName,'aria-labelledby':'healthEmergencyQuestion'});first.options=[new Element('option',{value:'true'},'Yes'),new Element('option',{value:'false'},'No')];const second=new Element('input',{name:secondName,type:'radio',value:'false'});const group=new Element('div',{class:'form-group'},'Do you have a permanent injury? ',[second,new Element('span',{},'No')]);const third=new Element('input',{name:thirdName,type:'radio',value:'true'}),personal=new Element('input',{name:'Applicant.Name',type:'text'});const mixed=new Element('div',{class:'form-group'},'PRIVATE_APPLICANT_NAME ',[third,personal]);const result=await inspectPortalPage(mockPage([heading,first,group,mixed],{url:OFFICIAL+'/SmartForm/HealthInsuranceInfo/123'}));assert.match(result.healthQuestions[0].question,/Are you receiving emergency treatment/);assert.equal(result.healthQuestions[0].source,'aria_labelledby');assert.equal(result.healthQuestions[0].question.includes('owner@'),false);assert.equal(result.healthQuestions[0].question.includes('123456789'),false);assert.equal(result.healthQuestions[1].question,'Do you have a permanent injury?');assert.equal(result.healthQuestions[2].question,null);assert.equal(JSON.stringify(result.healthQuestions).includes('PRIVATE_'),false);});

test('health question metadata is bounded and never follows similar routes or hidden controls',async()=>{const name='DeclarationForms[0].Q1_IsReceivingEmergencyTreatment',field=new Element('input',{name,type:'radio',value:'true','aria-labelledby':'longQuestion'}),heading=new Element('p',{id:'longQuestion'},'Public question '.repeat(1000)),hidden=new Element('input',{name:'DeclarationForms[0].Q2_HavePermenantInjury',type:'hidden',value:'PRIVATE_HIDDEN'});const result=await inspectPortalPage(mockPage([field,heading,hidden],{url:OFFICIAL+'/SmartForm/HealthInsuranceInfo/123'}));assert.equal(result.healthQuestions.length,1);assert.equal(result.healthQuestions[0].question.length,600);for(const path of ['/SmartForm/HealthInsuranceInfoExtra/123','/Account/HealthInsuranceInfo/123','/SmartForm/HealthInsuranceInfo/123/extra']){const other=await inspectPortalPage(mockPage([field,heading],{url:OFFICIAL+path}));assert.equal(Object.hasOwn(other,'healthQuestions'),false);}});

test('numeric health insurance quote route returns actual public company row cells without price assumptions or checked values',async()=>{const make=(name,choice,price)=>{const radio=new Element('input',{name:'CompanyNumber',type:'radio',value:choice});Object.defineProperty(radio,'checked',{get(){throw Error('QUOTE_SELECTION_READ');}});const company=new Element('label',{},name,[radio]);radio.labels=[company];const hidden=new Element('span',{},'PRIVATE_HIDDEN_PRICE');hidden.hidden=true;return new Element('tr',{},'',[new Element('td',{},'',[company]),new Element('td',{},price,[hidden,new Element('input',{type:'hidden',value:'PRIVATE_HIDDEN_FIELD'})]),new Element('td',{},'SAR'),new Element('td',{},'شامل الضريبة')]);};const table=new Element('table',{},'',[new Element('tr',{},'',[new Element('th',{},'شركة التأمين'),new Element('th',{},'السعر'),new Element('th',{},'العملة'),new Element('th',{},'تفاصيل')]),make('Insurance Alpha','101','1000.50'),make('Insurance Beta','202','USD 14.65')]);const result=await inspectPortalPage(mockPage([table],{url:OFFICIAL+'/SmartForm/HealthInsurance/123456789?private=SECRET'}));const quotes=result.insuranceQuotes;assert.equal(quotes.available,true);assert.equal(quotes.offers.length,2);assert.deepEqual(Array.from(quotes.offers[0].cells),['Insurance Alpha','1000.50','SAR','شامل الضريبة']);assert.equal(quotes.offers[1].cells[1],'USD 14.65');assert.equal(quotes.offers[0].publicChoice,'101');assert.equal(quotes.offers[0].companyLabel,'Insurance Alpha');assert.ok(quotes.offers.every(offer=>!Object.hasOwn(offer,'price')&&!Object.hasOwn(offer,'currency')&&!Object.hasOwn(offer,'checked')));assert.equal(JSON.stringify(quotes).includes('PRIVATE_'),false);const other=await inspectPortalPage(mockPage([table]));assert.equal(Object.hasOwn(other,'insuranceQuotes'),false);});

test('insurance quote metadata refuses mixed personal rows and unsafe or unassociated company values',async()=>{const make=(value,withLabel=true)=>{const radio=new Element('input',{name:'CompanyNumber',type:'radio',value});if(withLabel)radio.labels=[label('Insurance Alpha')];return new Element('tr',{},'',[new Element('td',{},'Insurance Alpha',[radio]),new Element('td',{},'SAR 15.00')]);};for(const extras of [[new Element('tr',{},'',[new Element('td',{},'PRIVATE_APPLICANT_NAME')])],[new Element('tr',{},'',[new Element('th',{},'Passport number')])],[new Element('tr',{},'',[new Element('td',{},'',[new Element('input',{name:'Applicant.Name'})])])]]){const table=new Element('table',{},'',[make('101'),...extras]);const result=await inspectPortalPage(mockPage([table],{url:OFFICIAL+'/SmartForm/HealthInsurance/123'}));assert.equal(result.insuranceQuotes.available,false);assert.equal(result.insuranceQuotes.offers.length,0);}for(const row of [make('PRIVATE_OPAQUE'),make('101',false)]){const result=await inspectPortalPage(mockPage([new Element('table',{},'',[row])],{url:OFFICIAL+'/SmartForm/HealthInsurance/123'}));assert.equal(result.insuranceQuotes.available,false);}});

test('insurance quotes bound offers cells and text and reject nonnumeric reference routes',async()=>{const make=index=>{const radio=new Element('input',{name:'CompanyNumber',type:'radio',value:String(100+index)});radio.labels=[label('Public insurance company')];return new Element('tr',{},'',[new Element('td',{},'',[radio]),...Array.from({length:12},()=>new Element('td',{},'Public price information '.repeat(20)))]);};const table=new Element('table',{},'',[make(0)]),result=await inspectPortalPage(mockPage([table],{url:OFFICIAL+'/SmartForm/HealthInsurance/123'}));assert.equal(result.insuranceQuotes.available,true);assert.equal(result.insuranceQuotes.offers[0].cells.length,10);assert.ok(result.insuranceQuotes.offers[0].cells.every(cell=>cell.length<=120));const tooMany=await inspectPortalPage(mockPage([new Element('table',{},'',Array.from({length:31},(_,i)=>make(i)))],{url:OFFICIAL+'/SmartForm/HealthInsurance/123'}));assert.equal(tooMany.insuranceQuotes.available,false);for(const path of ['/SmartForm/HealthInsurance/private-ref','/SmartForm/HealthInsuranceInfo/123','/SmartForm/HealthInsurance/123/extra']){const other=await inspectPortalPage(mockPage([table],{url:OFFICIAL+path}));assert.equal(Object.hasOwn(other,'insuranceQuotes'),false);}});
